def compute(vars):
    cost_millions = vars["v1"]
    recognition_period_years = vars["v2"]

    if recognition_period_years == 0:
        return None

    annual_recognition_millions = cost_millions / recognition_period_years

    return {
        "value": annual_recognition_millions,
        "trace": {
            "cost_millions": cost_millions,
            "recognition_period_years": recognition_period_years,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "per year"
            }
        }
    }
